from pathlib import Path
import base64, hashlib, subprocess, sys, zlib

root = Path(sys.argv[1]).resolve()
payload = ''
patch = zlib.decompress(base64.b64decode(payload))
expected = '0c4e6b77df87e2ae303162600f4a9ac4a0460e67196c3d3bf8d41660623bd8af'
actual = hashlib.sha256(patch).hexdigest()
if actual != expected:
    raise RuntimeError(f"alpha52 contracts patch checksum mismatch: {actual} != {expected}")
subprocess.run(["git", "-C", str(root), "apply", "--whitespace=nowarn", "-"], input=patch, check=True)
print("PKVault V8 alpha52 contracts board + tracking applied")
